def _anq(rows, heads, cols, widths):
    """Given figures in A:C, answers in the columns of heads; rows: [(label, values...)]."""
    d, g, f, st = {'A1': heads[0]}, {}, {}, {}
    for j, h in enumerate(heads[1:]): d[f'{chr(66 + j)}1'] = h
    for j in range(len(heads)): st[f'{chr(65 + j)}1'] = {'fill': '#e1e7f8', 'b': True}
    for i, row in enumerate(rows):
        r = 2 + i; d[f'A{r}'] = row[0]
        for j, v in enumerate(row[1:]): g[f'{chr(66 + j)}{r}'] = v; f[f'{chr(66 + j)}{r}'] = 'acc0'
    return d, g, f, st


